add='''#[test]
fn hook_registry_passes_tool_handlers_a_child_context_of_active_hook_span() {
    let telemetry = InMemoryTelemetryContext::new();
    let hooks = HookRegistry::new(|_| {});
    let received = Arc::new(Mutex::new(None));
    let output = Arc::clone(&received);
    hooks.on_before_tool(move |context| {
        *output.lock().unwrap() = context.values.get("hook.test.value").cloned();
        if let HookTelemetryParent::Span(span) = &context.telemetry {
            span.start_span(SpanOptions::new("handler.child"), |_| Ok::<_, String>(()))?;
        }
        Ok(())
    });
    let (gate, _) = gate();
    telemetry
        .start_span(SpanOptions::new("invocation"), |span| {
            hooks.run_before_tool(
                &ToolHookContext {
                    values: BTreeMap::from([("hook.test.value".into(), "preserved".into())]),
                    telemetry: HookTelemetryParent::Span(span.clone()),
                },
                &gate,
            )
        })
        .unwrap();
    assert_eq!(received.lock().unwrap().as_deref(), Some("preserved"));
    let spans = telemetry.spans();
    let invocation = spans.iter().find(|span| span.name == "invocation").unwrap();
    let hook = spans.iter().find(|span| span.name == "pi.harness.hook").unwrap();
    let child = spans.iter().find(|span| span.name == "handler.child").unwrap();
    assert_eq!(hook.parent_id, Some(invocation.id));
    assert_eq!(child.parent_id, Some(hook.id));
}

#[test]
