fn event_bus_continues_watcher_delivery_after_listener_failure_and_reports_it() {
    let bus = HarnessEventBus::new();
    let failures = Arc::new(Mutex::new(Vec::new()));
    let output = Arc::clone(&failures);
    bus.on("handler_error", move |event, _| {
        output.lock().unwrap().push(event.fields["error"].as_str().unwrap().to_owned());
        Ok(())
    }).unwrap();
    let watcher = bus.watch((), |event| event.event_type == "run_start").unwrap();
    let seen = Arc::new(Mutex::new(Vec::new()));
    let output = Arc::clone(&seen);
    watcher.start(move |event, _| {
        let id = run_id(&event);
        if id == "one" { return Err("watcher failed".into()); }
        output.lock().unwrap().push(id);
        Ok(())
    }).unwrap();
    bus.emit(run("one"), context("x"));
    bus.emit(run("two"), context("x"));
    assert_eq!(*seen.lock().unwrap(), ["two"]);
    assert_eq!(*failures.lock().unwrap(), ["watcher failed"]);
}

